// Code de mes TP R5.A.05 (groupe 5, serveur Flask de l’IUT) : jeton InfluxDB masqué. Base Chinook (licence MIT) réduite aux tables artists et albums.
window.COURS_FILES = Object.assign(window.COURS_FILES || {}, {"flask-tp2": {"app/routes.py": "from flask import Blueprint, render_template\nfrom sqlalchemy.orm import selectinload\n\nfrom app.models import Artist, Album\n\nmain_bp = Blueprint(\"main\", __name__)\n\n\n@main_bp.route(\"/\")\ndef index():\n    return render_template(\n        \"artists.html\",\n        title=\"Chinook Database\",\n        heading=\"Chinook Database\",\n        count=0,\n        count_label=\"records\",\n        mode=\"home\",\n        items=[],\n    )\n\n\n@main_bp.route(\"/artists\")\ndef artists():\n    artist_rows = Artist.query.order_by(Artist.Name).all()\n    return render_template(\n        \"artists.html\",\n        title=\"Artists\",\n        heading=\"Artists\",\n        count=len(artist_rows),\n        count_label=\"artists\",\n        mode=\"artists\",\n        items=artist_rows,\n    )\n\n\n@main_bp.route(\"/albums\")\ndef albums():\n    album_rows = Album.query.order_by(Album.Title).all()\n    return render_template(\n        \"artists.html\",\n        title=\"Albums\",\n        heading=\"Albums\",\n        count=len(album_rows),\n        count_label=\"albums\",\n        mode=\"albums\",\n        items=album_rows,\n    )\n\n\n@main_bp.route(\"/artists-with-albums\")\n@main_bp.route(\"/artists with albums\")\ndef artists_with_albums():\n    artist_rows = (\n        Artist.query.options(selectinload(Artist.albums))\n        .join(Artist.albums)\n        .distinct()\n        .order_by(Artist.Name)\n        .all()\n    )\n    return render_template(\n        \"artists.html\",\n        title=\"Artists with Albums\",\n        heading=\"Artists with Albums\",\n        count=len(artist_rows),\n        count_label=\"artists\",\n        mode=\"artists_with_albums\",\n        items=artist_rows,\n    )", "app/models.py": "from sqlalchemy import ForeignKey\nfrom sqlalchemy.orm import Mapped, mapped_column, relationship\n\nfrom app import db\n\n\nclass Artist(db.Model):\n    __tablename__ = \"artists\"\n\n    ArtistId: Mapped[int] = mapped_column(primary_key=True)\n    Name: Mapped[str]\n\n    albums: Mapped[list[\"Album\"]] = relationship(back_populates=\"artist\")\n\n\nclass Album(db.Model):\n    __tablename__ = \"albums\"\n\n    AlbumId: Mapped[int] = mapped_column(primary_key=True)\n    Title: Mapped[str]\n    ArtistId: Mapped[int] = mapped_column(ForeignKey(\"artists.ArtistId\"))\n\n    artist: Mapped[Artist] = relationship(back_populates=\"albums\")", "app/__init__.py": "from flask import Flask\nfrom flask_sqlalchemy import SQLAlchemy\nfrom sqlalchemy.orm import DeclarativeBase\n\nfrom config import Config\n\n\nclass Base(DeclarativeBase):\n    pass\n\n\ndb = SQLAlchemy(model_class=Base)\n\n\ndef create_app(config_class=Config):\n    app = Flask(__name__)\n    app.config.from_object(config_class)\n\n    db.init_app(app)\n\n    from app.routes import main_bp\n    app.register_blueprint(main_bp)\n\n    return app", "config.py": "from pathlib import Path\n\n\nclass Config:\n    database_path = Path(__file__).resolve().parent / \"chinook.db\"\n    SQLALCHEMY_DATABASE_URI = f\"sqlite:///{database_path}\"\n    SQLALCHEMY_TRACK_MODIFICATIONS = False", "run.py": "from app import create_app\n\napp = create_app()\n\nif __name__ == \"__main__\":\n    app.run(host=\"0.0.0.0\", port=5005, debug=True)", "app/templates/artists.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n\t<meta charset=\"UTF-8\">\n\t<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n\t<title>{{ title or \"Chinook\" }}</title>\n\t<style>\n\t\tbody {\n\t\t\tfont-family: Arial, sans-serif;\n\t\t\tmargin: 2rem;\n\t\t\tline-height: 1.5;\n\t\t}\n\n\t\th1 {\n\t\t\tmargin-bottom: 0.25rem;\n\t\t}\n\n\t\t.count {\n\t\t\tmargin-top: 0;\n\t\t\tcolor: #555;\n\t\t}\n\n\t\t.artist-name {\n\t\t\tfont-weight: bold; /* Bold only the artist’s name */\n\t\t}\n\n\t\t.album-list {\n\t\t\tmargin-left: 20px; /* Add indentation to album titles */\n\t\t}\n\n\t\t.records {\n\t\t\tpadding-left: 1.25rem;\n\t\t}\n\n\t\t.records li {\n\t\t\tmargin-bottom: 0.75rem;\n\t\t}\n\t</style>\n</head>\n<body>\n\t<h1>{{ heading or title }}</h1>\n\t<p class=\"count\">{{ count }} {{ count_label }}</p>\n\n\t{% if mode == 'artists' %}\n\t\t<ul class=\"records\">\n\t\t\t{% for artist in items %}\n\t\t\t\t<li>\n\t\t\t\t\t<span class=\"artist-name\">{{ artist.Name }}</span>\n\t\t\t\t\t<span>(ID: {{ artist.ArtistId }})</span>\n\t\t\t\t</li>\n\t\t\t{% endfor %}\n\t\t</ul>\n\t{% elif mode == 'albums' %}\n\t\t<ul class=\"records\">\n\t\t\t{% for album in items %}\n\t\t\t\t<li>\n\t\t\t\t\t<span class=\"artist-name\">{{ album.Title }}</span>\n\t\t\t\t\t<span>(Artist ID: {{ album.ArtistId }})</span>\n\t\t\t\t</li>\n\t\t\t{% endfor %}\n\t\t</ul>\n\t{% elif mode == 'artists_with_albums' %}\n\t\t<ul class=\"records\">\n\t\t\t{% for artist in items %}\n\t\t\t\t<li>\n\t\t\t\t\t<span class=\"artist-name\">{{ artist.Name }}</span>\n\t\t\t\t\t<ul class=\"album-list\">\n\t\t\t\t\t\t{% for album in artist.albums %}\n\t\t\t\t\t\t\t<li>{{ album.Title }}</li>\n\t\t\t\t\t\t{% else %}\n\t\t\t\t\t\t\t<li>No album available</li>\n\t\t\t\t\t\t{% endfor %}\n\t\t\t\t\t</ul>\n\t\t\t\t</li>\n\t\t\t{% endfor %}\n\t\t</ul>\n\t{% else %}\n\t\t<p>Choose a route to view artists, albums, or artists with albums.</p>\n\t{% endif %}\n</body>\n</html>", "app/templates/heatindex.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Heat Index</title>\n</head>\n<body>\n    <h1>Heat Index Calculator</h1>\n    <p>This is a simple heat index calculator.</p>\n\n    <form action=\"/heatindex\" method=\"post\">\n        <div>\n            <label for=\"temperature\">Temperature (°C):</label>\n            <input type=\"text\" id=\"temperature\" name=\"temperature\" min=\"-20\" max=\"50\" value=\"25\" required>\n        </div>\n        <br><br>\n        <div>\n            <label for=\"humidity\">Humidity (%):</label>\n            <input type=\"text\" id=\"humidity\" name=\"humidity\" required>\n        </div>\n        <br><br>\n        <input type=\"submit\" value=\"Calculate Heat Index\">\n    </form>\n\n    {% if result is not none %}\n        <h2>Result: {{ result }}</h2>\n    {% endif %}\n\n    <script>\n        function bindSliderValue(sliderId, valueId) {\n            const slider = document.getElementById(sliderId);\n            const valueLabel = document.getElementById(valueId);\n\n            function update() {\n                valueLabel.textContent = slider.value;\n            }\n\n            slider.addEventListener('input', update);\n            update();\n        }\n\n        bindSliderValue('temperature', 'temperature-value');\n        bindSliderValue('humidity', 'humidity-value');\n    </script>\n</body>\n</html>\n\n", "Dockerfile": "FROM python:3.10-slim\n\nWORKDIR /TP2\n\nCOPY . /TP2\n\nRUN pip install --no-cache-dir Flask Flask-SQLAlchemy SQLAlchemy\n\nEXPOSE 5005\n\nCMD [\"python\", \"run.py\"]", ".dockerignore": "__pycache__/\n*.pyc\n*.pyo\n*.pyd\n.git/\n.gitignore\n.venv/\nvenv/\n.env\n.DS_Store\n"}, "flask-tp3": {"app.py": "import os\nimport re\nfrom collections import defaultdict\nfrom typing import Any\n\nfrom flask import Flask, render_template, request\nfrom influxdb_client import InfluxDBClient\n\n\nCHART_COLORS = [\n    \"#64d2ff\",\n    \"#7cf29a\",\n    \"#f2c94c\",\n    \"#ff8a65\",\n    \"#c792ea\",\n    \"#ff6b8a\",\n    \"#4dd0e1\",\n    \"#a7ff83\",\n]\n\nWEATHER_CURRENT_FIELDS = [\n    (\"apparent_temperature\", \"Apparent temperature\"),\n    (\"temperature_2m\", \"Temperature 2m\"),\n    (\"cloud_cover\", \"Cloud cover\"),\n    (\"relative_humidity_2m\", \"Humidity\"),\n    (\"precipitation\", \"Precipitation\"),\n    (\"surface_pressure\", \"Surface pressure\"),\n    (\"weather_code\", \"Weather code\"),\n    (\"wind_speed_10m\", \"Wind speed\"),\n    (\"wind_direction_10m\", \"Wind direction\"),\n]\n\nWEATHER_FORECAST_FIELDS = [\n    (\"temperature_2m\", \"Temperature 2m\"),\n    (\"weather_code\", \"Weather code\"),\n    (\"wind_speed_18m\", \"Wind speed 18m\"),\n]\n\n\napp = Flask(__name__)\napp.config[\"INFLUXDB_V2_URL\"] = os.getenv(\"INFLUXDB_V2_URL\", \"http://192.168.168.88:8086\")\napp.config[\"INFLUXDB_V2_ORG\"] = os.getenv(\"INFLUXDB_V2_ORG\", \"iut\")\napp.config[\"INFLUXDB_V2_TOKEN\"] = os.getenv(\"INFLUXDB_V2_TOKEN\", \"\")\n\n\ndef influx_ready() -> bool:\n    return bool(app.config[\"INFLUXDB_V2_TOKEN\"].strip())\n\n\ndef get_client() -> InfluxDBClient | None:\n    if not influx_ready():\n        return None\n\n    return InfluxDBClient(\n        url=app.config[\"INFLUXDB_V2_URL\"],\n        token=app.config[\"INFLUXDB_V2_TOKEN\"],\n        org=app.config[\"INFLUXDB_V2_ORG\"],\n    )\n\n\ndef render_page(**context: Any):\n    base_context = {\n        \"url\": app.config[\"INFLUXDB_V2_URL\"],\n        \"org\": app.config[\"INFLUXDB_V2_ORG\"],\n        \"token_set\": influx_ready(),\n        \"weather_current_options\": [],\n        \"weather_forecast_options\": [],\n        \"selected_weather_current_fields\": [],\n        \"selected_weather_forecast_fields\": [],\n        \"routes\": [\n            {\"label\": \"Dashboard\", \"path\": \"/\"},\n            {\"label\": \"Weather query\", \"path\": \"/query?bucket=weather\"},\n            {\"label\": \"Forex query\", \"path\": \"/query?bucket=forex\"},\n            {\"label\": \"Crypto query\", \"path\": \"/query?bucket=crypto\"},\n            {\"label\": \"System query\", \"path\": \"/query?bucket=system\"},\n        ],\n    }\n    base_context.update(context)\n    return render_template(\"index.html\", **base_context)\n\n\ndef format_timestamp(value: Any) -> str:\n    if hasattr(value, \"strftime\"):\n        return value.strftime(\"%Y-%m-%d %H:%M\")\n    return str(value)\n\n\ndef format_metric_value(value: Any) -> str:\n    if isinstance(value, (int, float)):\n        number = float(value)\n        magnitude = abs(number)\n        if magnitude >= 1000:\n            return f\"{number:,.0f}\"\n        if magnitude >= 100:\n            return f\"{number:,.1f}\"\n        if magnitude >= 10:\n            return f\"{number:.2f}\"\n        return f\"{number:.3f}\".rstrip(\"0\").rstrip(\".\")\n    return str(value)\n\n\ndef parse_selected_fields(raw_fields: list[str], allowed_fields: list[str], fallback_fields: list[str]) -> list[str]:\n    selected = [field for field in raw_fields if field in allowed_fields]\n    return selected or fallback_fields\n\n\ndef make_field_filter(fields: list[str]) -> str:\n    if not fields:\n        return 'true'\n\n    if len(fields) == 1:\n        return f'r._field == \"{fields[0]}\"'\n\n    return ' or '.join(f'r._field == \"{field}\"' for field in fields)\n\n\ndef query_flux(flux_query: str) -> tuple[bool, str, list[dict[str, Any]]]:\n    client = get_client()\n    if client is None:\n        return False, \"InfluxDB token not configured yet.\", []\n\n    try:\n        tables = client.query_api().query(org=app.config[\"INFLUXDB_V2_ORG\"], query=flux_query)\n        records: list[dict[str, Any]] = []\n        for table in tables:\n            for record in table.records:\n                records.append(dict(record.values))\n        return True, f\"Returned {len(records)} rows.\", records\n    except Exception as error:  # pragma: no cover - depends on network/service availability\n        return False, str(error), []\n    finally:\n        client.close()\n\n\ndef query_scalar_values(flux_query: str) -> tuple[bool, str, list[str]]:\n    ok, message, records = query_flux(flux_query)\n    if not ok:\n        return ok, message, []\n\n    values: list[str] = []\n    for record in records:\n        value = record.get(\"_value\")\n        if value is not None:\n            values.append(str(value))\n\n    unique_values = list(dict.fromkeys(values))\n    return True, f\"Found {len(unique_values)} values.\", unique_values\n\n\ndef get_tag_values(bucket_name: str, tag_name: str) -> list[str]:\n    flux_query = f'''\nimport \"influxdata/influxdb/schema\"\nschema.tagValues(bucket: \"{bucket_name}\", tag: \"{tag_name}\")\n'''\n    ok, _message, values = query_scalar_values(flux_query)\n    return values if ok else []\n\n\ndef group_time_series(records: list[dict[str, Any]], series_label_fields: list[str]) -> tuple[list[str], list[dict[str, Any]]]:\n    grouped: dict[str, dict[str, Any]] = defaultdict(lambda: {\"points\": {}, \"latest_time\": None, \"latest_value\": None})\n    labels: set[str] = set()\n\n    for record in records:\n        raw_value = record.get(\"_value\")\n        raw_time = record.get(\"_time\")\n        if raw_value is None or raw_time is None:\n            continue\n\n        if not isinstance(raw_value, (int, float)):\n            continue\n\n        series_parts = [str(record.get(field)) for field in series_label_fields if record.get(field) not in (None, \"\")]\n        series_name = \" / \".join(series_parts) if series_parts else str(record.get(\"_field\") or record.get(\"_measurement\") or \"series\")\n        timestamp = format_timestamp(raw_time)\n        value = float(raw_value)\n\n        payload = grouped[series_name]\n        payload[\"points\"][timestamp] = value\n        labels.add(timestamp)\n\n        latest_time = payload[\"latest_time\"]\n        if latest_time is None or raw_time > latest_time:\n            payload[\"latest_time\"] = raw_time\n            payload[\"latest_value\"] = value\n\n    ordered_labels = sorted(labels)\n    series: list[dict[str, Any]] = []\n    for index, (series_name, payload) in enumerate(sorted(grouped.items())):\n        series.append(\n            {\n                \"label\": series_name,\n                \"values\": [payload[\"points\"].get(label) for label in ordered_labels],\n                \"latest_value\": payload[\"latest_value\"],\n                \"latest_time\": format_timestamp(payload[\"latest_time\"]) if payload[\"latest_time\"] else None,\n                \"color\": CHART_COLORS[index % len(CHART_COLORS)],\n            }\n        )\n\n    return ordered_labels, series\n\n\ndef build_chart_panel(\n    title: str,\n    subtitle: str,\n    flux_query: str,\n    series_label_fields: list[str],\n    value_unit: str,\n    show_chart: bool = True,\n    action_link: str | None = None,\n    action_label: str = \"Open evolution\",\n) -> dict[str, Any]:\n    ok, message, records = query_flux(flux_query)\n    labels, series = group_time_series(records, series_label_fields) if ok else ([], [])\n\n    datasets: list[dict[str, Any]] = []\n    for item in series:\n        datasets.append(\n            {\n                \"label\": item[\"label\"],\n                \"data\": item[\"values\"],\n                \"borderColor\": item[\"color\"],\n                \"backgroundColor\": item[\"color\"],\n                \"fill\": False,\n                \"tension\": 0.35,\n                \"pointRadius\": 0,\n                \"borderWidth\": 2,\n            }\n        )\n\n    stats = [\n        {\n            \"label\": item[\"label\"],\n            \"value\": format_metric_value(item[\"latest_value\"]),\n            \"time\": item[\"latest_time\"],\n        }\n        for item in series\n        if item[\"latest_value\"] is not None\n    ]\n\n    return {\n        \"title\": title,\n        \"subtitle\": subtitle,\n        \"message\": message,\n        \"query\": flux_query,\n        \"labels\": labels,\n        \"datasets\": datasets,\n        \"stats\": stats,\n        \"series_count\": len(series),\n        \"point_count\": sum(len(item[\"values\"]) for item in series),\n        \"value_unit\": value_unit,\n        \"has_data\": show_chart and bool(labels and datasets),\n        \"action_link\": action_link,\n        \"action_label\": action_label,\n    }\n\n\ndef build_dashboard(\n    location: str,\n    base_currency: str,\n    forex_quotes: list[str],\n    crypto_symbols: list[str],\n    weather_current_fields: list[str],\n    weather_forecast_fields: list[str],\n) -> list[dict[str, Any]]:\n    symbol_regex = \"|\".join(re.escape(symbol) for symbol in crypto_symbols)\n    quote_regex = \"|\".join(re.escape(quote) for quote in forex_quotes)\n    weather_current_field_filter = make_field_filter(weather_current_fields)\n    weather_forecast_field_filter = make_field_filter(weather_forecast_fields)\n\n    weather_query = f'''\nfrom(bucket: \"weather\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"weather_current\")\n  |> filter(fn: (r) => r.location == \"{location}\")\n  |> filter(fn: (r) => {weather_current_field_filter})\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n\n    weather_forecast_query = f'''\nfrom(bucket: \"weather\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"weather_forecast\")\n  |> filter(fn: (r) => r.location == \"{location}\")\n  |> filter(fn: (r) => {weather_forecast_field_filter})\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n\n    forex_query = f'''\nfrom(bucket: \"forex\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"forex\")\n  |> filter(fn: (r) => r.base == \"{base_currency}\")\n    |> filter(fn: (r) => r.quote =~ /^{quote_regex}$/)\n  |> filter(fn: (r) => r._field == \"rate\")\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n\n    crypto_query = f'''\nfrom(bucket: \"crypto\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"crypto\")\n  |> filter(fn: (r) => r._field == \"price\")\n  |> filter(fn: (r) => r.symbol =~ /^{symbol_regex}$/)\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n\n    system_query = '''\nfrom(bucket: \"system\")\n  |> range(start: -24h)\n  |> filter(fn: (r) => r._measurement == \"cpu\")\n  |> filter(fn: (r) => r.cpu == \"cpu-total\")\n  |> filter(fn: (r) => r._field == \"usage_user\" or r._field == \"usage_system\" or r._field == \"usage_idle\")\n  |> aggregateWindow(every: 5m, fn: mean, createEmpty: false)\n'''\n\n    return [\n        build_chart_panel(\n            title=\"Weather current\",\n            subtitle=f\"{location} current conditions: {', '.join(weather_current_fields)}\",\n            flux_query=weather_query,\n            series_label_fields=[\"_field\"],\n            value_unit=\"°C\",\n        ),\n        build_chart_panel(\n            title=\"Weather forecast\",\n            subtitle=f\"{location} forecast fields: {', '.join(weather_forecast_fields)}\",\n            flux_query=weather_forecast_query,\n            series_label_fields=[\"_field\"],\n            value_unit=\"°C\",\n        ),\n        build_chart_panel(\n            title=\"Forex current prices\",\n            subtitle=f\"{base_currency} exchange rates: {', '.join(forex_quotes)}\",\n            flux_query=forex_query,\n            series_label_fields=[\"quote\"],\n            value_unit=\"rate\",\n            show_chart=False,\n            action_link=f\"/query?bucket=forex&base={base_currency}\" + \"\".join(f\"&quotes={quote}\" for quote in forex_quotes),\n            action_label=\"View forex evolution\",\n        ),\n        build_chart_panel(\n            title=\"Crypto current prices\",\n            subtitle=f\"Selected symbols: {', '.join(crypto_symbols)}\",\n            flux_query=crypto_query,\n            series_label_fields=[\"symbol\"],\n            value_unit=\"price\",\n            show_chart=False,\n            action_link=\"/query?bucket=crypto\" + \"\".join(f\"&symbols={symbol}\" for symbol in crypto_symbols),\n            action_label=\"View crypto evolution\",\n        ),\n        build_chart_panel(\n            title=\"System\",\n            subtitle=\"CPU usage on the host\",\n            flux_query=system_query,\n            series_label_fields=[\"_field\"],\n            value_unit=\"%\",\n        ),\n    ]\n\n\n@app.route(\"/\")\ndef index():\n    weather_locations = get_tag_values(\"weather\", \"location\")\n    forex_base_options = get_tag_values(\"forex\", \"base\")\n    forex_quote_options = get_tag_values(\"forex\", \"quote\")\n    crypto_symbol_options = get_tag_values(\"crypto\", \"symbol\")\n\n    location = request.args.get(\"location\", weather_locations[0] if weather_locations else \"annecy\")\n    base_currency = request.args.get(\"base\", forex_base_options[0] if forex_base_options else \"USD\")\n    forex_quotes = [symbol.strip() for symbol in request.args.get(\"quotes\", \"\").split(\",\") if symbol.strip()]\n    if not forex_quotes:\n        forex_quotes = forex_quote_options[:5] if forex_quote_options else [\"EUR\", \"GBP\", \"JPY\", \"CHF\", \"CAD\"]\n    crypto_symbols = [symbol.strip() for symbol in request.args.get(\"symbols\", \"\").split(\",\") if symbol.strip()]\n    if not crypto_symbols:\n        crypto_symbols = crypto_symbol_options[:5] if crypto_symbol_options else [\"BTCUSDT\", \"ETHUSDT\", \"BNBUSDT\", \"ADAUSDT\", \"DOGEUSDT\"]\n    current_field_choices = [field for field, _label in WEATHER_CURRENT_FIELDS]\n    forecast_field_choices = [field for field, _label in WEATHER_FORECAST_FIELDS]\n    weather_current_fields = parse_selected_fields(request.args.getlist(\"weather_current_fields\"), current_field_choices, [\"temperature_2m\", \"apparent_temperature\"])\n    weather_forecast_fields = parse_selected_fields(request.args.getlist(\"weather_forecast_fields\"), forecast_field_choices, [\"temperature_2m\", \"weather_code\", \"wind_speed_18m\"])\n\n    panels = build_dashboard(location, base_currency, forex_quotes, crypto_symbols, weather_current_fields, weather_forecast_fields)\n    return render_page(\n        title=\"InfluxDB Dashboard\",\n        heading=\"InfluxDB Dashboard\",\n        description=\"Grafana-style dashboard rendered from the InfluxDB buckets inside Docker.\",\n        dashboard=True,\n        panels=panels,\n        filters={\"location\": location, \"base\": base_currency, \"quotes\": \", \".join(forex_quotes), \"symbols\": \", \".join(crypto_symbols), \"weather_current_fields\": \", \".join(weather_current_fields), \"weather_forecast_fields\": \", \".join(weather_forecast_fields)},\n        controls_scope=\"dashboard\",\n        controls_action=\"/\",\n        controls_title=\"Update dashboard filters\",\n        controls_button_label=\"Update dashboard\",\n        controls_hint=\"Choose a city, market currencies, and weather fields.\",\n        controls_show_weather=True,\n        controls_show_forex=True,\n        controls_show_crypto=True,\n        weather_locations=weather_locations,\n        forex_base_options=forex_base_options or [base_currency],\n        forex_quote_options=forex_quote_options or forex_quotes,\n        crypto_symbol_options=crypto_symbol_options or crypto_symbols,\n        weather_current_options=WEATHER_CURRENT_FIELDS,\n        weather_forecast_options=WEATHER_FORECAST_FIELDS,\n        selected_weather_current_fields=weather_current_fields,\n        selected_weather_forecast_fields=weather_forecast_fields,\n        selected_location=location,\n        selected_base_currency=base_currency,\n        selected_forex_quotes=forex_quotes,\n        selected_crypto_symbols=crypto_symbols,\n        result_label=\"Token\",\n        result_value=\"configured\" if influx_ready() else \"missing\",\n        result_detail=\"Charts are driven by Flux queries against weather, forex, crypto, and system buckets.\",\n    )\n\n\n@app.route(\"/dashboard\")\ndef dashboard():\n    return index()\n\n\n@app.route(\"/ping\")\ndef ping():\n    client = get_client()\n    if client is None:\n        return render_page(\n            title=\"Ping InfluxDB\",\n            heading=\"Ping InfluxDB\",\n            description=\"Checks whether the InfluxDB connection is reachable.\",\n            result_label=\"Ping status\",\n            result_value=\"Not ready\",\n            result_detail=\"InfluxDB token not configured yet.\",\n        )\n\n    try:\n        response = client.ping()\n        ok = True\n        message = str(response)\n    except Exception as error:  # pragma: no cover - depends on network/service availability\n        ok = False\n        message = str(error)\n    finally:\n        client.close()\n\n    return render_page(\n        title=\"Ping InfluxDB\",\n        heading=\"Ping InfluxDB\",\n        description=\"Checks whether the InfluxDB connection is reachable.\",\n        result_label=\"Ping status\",\n        result_value=\"OK\" if ok else \"Not ready\",\n        result_detail=message,\n    )\n\n\n@app.route(\"/buckets\")\ndef buckets():\n    client = get_client()\n    if client is None:\n        return render_page(\n            title=\"Buckets\",\n            heading=\"Buckets\",\n            description=\"Bucket listing becomes available after the token is configured.\",\n            result_label=\"Bucket count\",\n            result_value=\"Unavailable\",\n            result_detail=\"Add INFLUXDB_V2_TOKEN to enable the InfluxDB client.\",\n            items=[],\n        )\n\n    try:\n        bucket_names = [bucket.name for bucket in client.buckets_api().find_buckets().buckets]\n        return render_page(\n            title=\"Buckets\",\n            heading=\"Buckets\",\n            description=\"Buckets available to the configured token.\",\n            result_label=\"Bucket count\",\n            result_value=str(len(bucket_names)),\n            result_detail=\"These names come from the InfluxDB API.\",\n            items=bucket_names,\n        )\n    except Exception as error:  # pragma: no cover - depends on network/service availability\n        return render_page(\n            title=\"Buckets\",\n            heading=\"Buckets\",\n            description=\"Buckets available to the configured token.\",\n            result_label=\"Bucket count\",\n            result_value=\"Error\",\n            result_detail=str(error),\n            items=[],\n        )\n    finally:\n        client.close()\n\n\n@app.route(\"/measurements/<bucket_name>\")\ndef measurements(bucket_name: str):\n    flux_query = f'''\nimport \"influxdata/influxdb/schema\"\nschema.measurements(bucket: \"{bucket_name}\")\n'''\n    ok, message, values = query_scalar_values(flux_query)\n    return render_page(\n        title=f\"Measurements - {bucket_name}\",\n        heading=f\"Measurements - {bucket_name}\",\n        description=\"Retrieves measurement names for a bucket.\",\n        result_label=\"Measurement count\",\n        result_value=str(len(values)) if ok else \"Unavailable\",\n        result_detail=message,\n        items=values,\n        query=flux_query,\n    )\n\n\n@app.route(\"/field-keys/<bucket_name>\")\ndef field_keys(bucket_name: str):\n    flux_query = f'''\nimport \"influxdata/influxdb/schema\"\nschema.fieldKeys(bucket: \"{bucket_name}\")\n'''\n    ok, message, values = query_scalar_values(flux_query)\n    return render_page(\n        title=f\"Field keys - {bucket_name}\",\n        heading=f\"Field keys - {bucket_name}\",\n        description=\"Retrieves field keys for a bucket.\",\n        result_label=\"Field key count\",\n        result_value=str(len(values)) if ok else \"Unavailable\",\n        result_detail=message,\n        items=values,\n        query=flux_query,\n    )\n\n\n@app.route(\"/query\")\ndef query_data():\n    bucket = request.args.get(\"bucket\", \"weather\")\n    weather_locations = get_tag_values(\"weather\", \"location\")\n    forex_base_options = get_tag_values(\"forex\", \"base\")\n    forex_quote_options = get_tag_values(\"forex\", \"quote\")\n    crypto_symbol_options = get_tag_values(\"crypto\", \"symbol\")\n\n    if bucket == \"weather\":\n        location = request.args.get(\"location\", weather_locations[0] if weather_locations else \"annecy\")\n        fields = request.args.getlist(\"fields\")\n        allowed_fields = [field for field, _label in WEATHER_CURRENT_FIELDS + WEATHER_FORECAST_FIELDS]\n        fields = parse_selected_fields(fields, allowed_fields, [\"temperature_2m\", \"apparent_temperature\"])\n        field_filter = make_field_filter(fields)\n        flux_query = f'''\nfrom(bucket: \"weather\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"weather_current\")\n  |> filter(fn: (r) => r.location == \"{location}\")\n  |> filter(fn: (r) => {field_filter})\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n        label_fields = [\"_field\"]\n    elif bucket == \"forex\":\n        base_currency = request.args.get(\"base\", forex_base_options[0] if forex_base_options else \"USD\")\n        selected_quotes = request.args.getlist(\"quotes\")\n        if not selected_quotes:\n            selected_quotes = forex_quote_options[:5] if forex_quote_options else []\n        quote_regex = \"|\".join(re.escape(quote) for quote in selected_quotes) if selected_quotes else \".*\"\n        flux_query = f'''\nfrom(bucket: \"forex\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"forex\")\n  |> filter(fn: (r) => r.base == \"{base_currency}\")\n  |> filter(fn: (r) => r.quote =~ /^{quote_regex}$/)\n  |> filter(fn: (r) => r._field == \"rate\")\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n        label_fields = [\"quote\"]\n    elif bucket == \"crypto\":\n        symbols = request.args.getlist(\"symbols\")\n        if len(symbols) == 1 and \",\" in symbols[0]:\n            symbols = [symbol.strip() for symbol in symbols[0].split(\",\") if symbol.strip()]\n        if not symbols:\n            symbols = crypto_symbol_options[:5] if crypto_symbol_options else [symbol.strip() for symbol in request.args.get(\"symbols\", \"BTCUSDT,ETHUSDT,BNBUSDT,ADAUSDT,DOGEUSDT\").split(\",\") if symbol.strip()]\n        symbol_regex = \"|\".join(re.escape(symbol) for symbol in symbols)\n        flux_query = f'''\nfrom(bucket: \"crypto\")\n  |> range(start: -7d)\n  |> filter(fn: (r) => r._measurement == \"crypto\")\n  |> filter(fn: (r) => r._field == \"price\")\n  |> filter(fn: (r) => r.symbol =~ /^{symbol_regex}$/)\n  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)\n'''\n        label_fields = [\"symbol\"]\n    elif bucket == \"system\":\n        flux_query = '''\nfrom(bucket: \"system\")\n  |> range(start: -24h)\n  |> filter(fn: (r) => r._measurement == \"cpu\")\n  |> filter(fn: (r) => r.cpu == \"cpu-total\")\n  |> filter(fn: (r) => r._field == \"usage_user\" or r._field == \"usage_system\" or r._field == \"usage_idle\")\n  |> aggregateWindow(every: 5m, fn: mean, createEmpty: false)\n'''\n        label_fields = [\"_field\"]\n    else:\n        flux_query = f'''\nfrom(bucket: \"{bucket}\")\n  |> range(start: -24h)\n  |> limit(n: 100)\n'''\n        label_fields = [\"_field\"]\n\n    ok, message, records = query_flux(flux_query)\n    labels, series = group_time_series(records, label_fields) if ok else ([], [])\n\n    query_rows = []\n    for record in records[:50]:\n        query_rows.append(\n            {\n                \"time\": format_timestamp(record.get(\"_time\")),\n                \"value\": format_metric_value(record.get(\"_value\")),\n                \"field\": record.get(\"_field\"),\n                \"measurement\": record.get(\"_measurement\"),\n                \"location\": record.get(\"location\") or record.get(\"base\") or record.get(\"quote\") or record.get(\"symbol\") or record.get(\"cpu\") or record.get(\"host\"),\n            }\n        )\n\n    dataset = []\n    numeric_values: list[float] = []\n    for record in records:\n        value = record.get(\"_value\")\n        if isinstance(value, (int, float)):\n            numeric_values.append(float(value))\n\n    window_size = 3\n    for index in range(len(numeric_values) - window_size):\n        dataset.append(\n            {\n                \"inputs\": numeric_values[index : index + window_size],\n                \"target\": numeric_values[index + window_size],\n            }\n        )\n\n    datasets = [\n        {\n            \"label\": item[\"label\"],\n            \"data\": item[\"values\"],\n            \"borderColor\": item[\"color\"],\n            \"backgroundColor\": item[\"color\"],\n            \"fill\": False,\n            \"tension\": 0.35,\n            \"pointRadius\": 0,\n            \"borderWidth\": 2,\n        }\n        for item in series\n    ]\n\n    return render_page(\n        title=f\"Query - {bucket}\",\n        heading=f\"Query - {bucket}\",\n        description=\"Raw Flux output plus a formatted dataset view.\",\n        result_label=\"Record count\",\n        result_value=str(len(records)) if ok else \"Unavailable\",\n        result_detail=message,\n        query=flux_query,\n        query_rows=query_rows,\n        dataset=dataset[:10],\n        dataset_size=len(dataset),\n        chart_block={\n            \"labels\": labels,\n            \"datasets\": datasets,\n            \"series_count\": len(series),\n            \"point_count\": sum(len(item[\"values\"]) for item in series),\n        },\n        controls_scope=bucket,\n        controls_action=f\"/query?bucket={bucket}\",\n        controls_title=f\"Update {bucket} evolution\",\n        controls_button_label=\"Update evolution\",\n        controls_hint=\"Select the city, currencies, or symbols to redraw the chart.\",\n        weather_locations=weather_locations,\n        forex_base_options=forex_base_options or [base_currency],\n        forex_quote_options=forex_quote_options or selected_quotes if bucket == \"forex\" else forex_quote_options,\n        crypto_symbol_options=crypto_symbol_options or symbols if bucket == \"crypto\" else crypto_symbol_options,\n        selected_location=location if bucket == \"weather\" else weather_locations[0] if weather_locations else \"annecy\",\n        selected_base_currency=base_currency if bucket == \"forex\" else forex_base_options[0] if forex_base_options else \"USD\",\n        selected_forex_quotes=selected_quotes if bucket == \"forex\" else [],\n        selected_crypto_symbols=symbols if bucket == \"crypto\" else [],\n        weather_current_options=WEATHER_CURRENT_FIELDS,\n        weather_forecast_options=WEATHER_FORECAST_FIELDS,\n        selected_weather_current_fields=fields if bucket == \"weather\" else [],\n        selected_weather_forecast_fields=fields if bucket == \"weather\" else [],\n    )\n\nif __name__ == \"__main__\":\n    app.run(host=\"0.0.0.0\", port=5005, debug=True)\n", "docker-compose.yml": "services:\n  influx_app:\n    build: .\n    ports:\n      - \"5005:5005\"\n    environment:\n      INFLUXDB_V2_URL: \"http://192.168.168.88:8086\"\n      INFLUXDB_V2_ORG: \"iut\"\n      INFLUXDB_V2_TOKEN: \"***\"\n    volumes:\n      - .:/TP3\n    container_name: Grp5_tp3_influx_starter\n", "Dockerfile": "FROM python:3.10-slim\n\nWORKDIR /TP3\n\nCOPY . /TP3\n\nRUN pip install --no-cache-dir Flask influxdb-client\n\nEXPOSE 5005\n\nCMD [\"python\", \"app.py\"]\n"}, "flask-tp4": {"exo.py": "from flask import Flask, render_template, request, jsonify, url_for\nimport base64\nimport io\nimport os\nfrom PIL import Image, ImageOps\nimport numpy as np\nfrom tensorflow.keras.models import load_model\n\n\napp = Flask(__name__, template_folder=\"app/templates\", static_folder=\"app/static\")\n\n\n# Project and model paths\nBASE_DIR = os.path.dirname(__file__)\nDEFAULT_MNIST_PATH = os.path.join(BASE_DIR, \"MNIST\", \"MNIST_keras_CNN.h5\")\nMODELS_DIR = os.path.join(BASE_DIR, \"models\")\n\n# Supported models and their expected preprocess behavior\nMODEL_CONFIG = {\n    \"mnist\": {\"display\": \"MNIST\", \"path\": DEFAULT_MNIST_PATH, \"type\": \"grayscale_28\"},\n    \"fashion_mnist\": {\"display\": \"Fashion-MNIST\", \"path\": os.path.join(MODELS_DIR, \"fashion_mnist.h5\"), \"type\": \"grayscale_28\"},\n    \"cifar10\": {\"display\": \"CIFAR-10\", \"path\": os.path.join(MODELS_DIR, \"cifar10.h5\"), \"type\": \"rgb_32\"},\n    \"cifar100\": {\"display\": \"CIFAR-100\", \"path\": os.path.join(MODELS_DIR, \"cifar100.h5\"), \"type\": \"rgb_32\"},\n}\n\nmodels_cache = {}\n\n\ndef load_model_for(name):\n    if name in models_cache:\n        return models_cache[name]\n    cfg = MODEL_CONFIG.get(name)\n    if not cfg:\n        raise ValueError(\"unknown model\")\n    path = cfg[\"path\"]\n    if not os.path.exists(path):\n        raise FileNotFoundError(f\"Model file not found: {path}\")\n    m = load_model(path, compile=False)\n    models_cache[name] = m\n    return m\n\n\ndef preprocess_data_url_for(name, data_url):\n    # get base64\n    if \",\" in data_url:\n        _, b64 = data_url.split(\",\", 1)\n    else:\n        b64 = data_url\n    data = base64.b64decode(b64)\n    img = Image.open(io.BytesIO(data))\n    cfg = MODEL_CONFIG.get(name)\n    if cfg is None:\n        raise ValueError(\"unknown model\")\n    t = cfg[\"type\"]\n    if t == \"grayscale_28\":\n        img = img.convert(\"L\")\n        # invert so drawn dark strokes become white like MNIST if background is white\n        img = ImageOps.invert(img)\n        img = img.resize((28, 28), Image.NEAREST)\n        arr = np.array(img).astype(\"float32\") / 255.0\n        arr = arr.reshape(1, 28, 28, 1)\n        return arr\n    elif t == \"rgb_32\":\n        img = img.convert(\"RGB\")\n        img = img.resize((32, 32), Image.BILINEAR)\n        arr = np.array(img).astype(\"float32\") / 255.0\n        arr = arr.reshape(1, 32, 32, 3)\n        return arr\n    else:\n        raise ValueError(\"unsupported preprocess type\")\n\n\n@app.route(\"/\")\ndef index():\n    # list available models and whether their files exist\n    models = []\n    for key, cfg in MODEL_CONFIG.items():\n        models.append({\n            \"name\": key,\n            \"display\": cfg.get(\"display\", key),\n            \"available\": os.path.exists(cfg[\"path\"]),\n            \"url\": url_for('model_page', model_name=key)\n        })\n    return render_template(\"index.html\", models=models)\n\n\n@app.route(\"/model/<model_name>\")\ndef model_page(model_name):\n    cfg = MODEL_CONFIG.get(model_name)\n    if cfg is None:\n        return \"Unknown model\", 404\n    return render_template(\"model.html\", model=model_name, display=cfg.get(\"display\", model_name), available=os.path.exists(cfg[\"path\"]))\n\n\n@app.route(\"/predict/<model_name>\", methods=[\"POST\"])\ndef predict_model(model_name):\n    cfg = MODEL_CONFIG.get(model_name)\n    if cfg is None:\n        return jsonify({\"error\": \"unknown model\"}), 400\n    if not os.path.exists(cfg[\"path\"]):\n        return jsonify({\"error\": \"model file not found on server\"}), 500\n\n    data = request.get_json(force=True)\n    if not data or \"image\" not in data:\n        return jsonify({\"error\": \"no image data\"}), 400\n\n    try:\n        x = preprocess_data_url_for(model_name, data[\"image\"])\n        m = load_model_for(model_name)\n        preds = m.predict(x)\n        # For CIFAR100/CIFAR10/fashion_mnist/mnist assume classification\n        digit = int(np.argmax(preds, axis=1)[0])\n        confidence = float(np.max(preds))\n        return jsonify({\"class\": digit, \"confidence\": confidence})\n    except Exception as e:\n        return jsonify({\"error\": str(e)}), 500\n\n\nif __name__ == \"__main__\":\n    print(\"* Starting Flask server on port 5005\")\n    app.run(host=\"0.0.0.0\", port=5005, debug=True)\n\n\n", "app/templates/model.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>{{ display }}</title>\n  </head>\n  <body>\n    <h1>{{ display }}</h1>\n    {% if not available %}\n      <p style=\"color:darkred\">Model file missing on server. Place the .h5 file at <code>TP4/app/models/{{ model }}.h5</code> or update configuration.</p>\n    {% endif %}\n\n    <p>Upload an image (or paste) to classify.</p>\n    <input type=\"file\" id=\"fileInput\" accept=\"image/*\">\n    <div>\n      <canvas id=\"preview\" width=\"280\" height=\"280\" style=\"border:1px solid #333\"></canvas>\n    </div>\n    <div>\n      <button id=\"predict\">Predict</button>\n      <button id=\"clear\">Clear</button>\n    </div>\n    <p id=\"result\">Result: -</p>\n\n    <script>\n    const fileInput = document.getElementById('fileInput');\n    const canvas = document.getElementById('preview');\n    const ctx = canvas.getContext('2d');\n    ctx.fillStyle = 'white'; ctx.fillRect(0,0,canvas.width,canvas.height);\n\n    fileInput.addEventListener('change', e=>{\n      const f = e.target.files[0];\n      if(!f) return;\n      const reader = new FileReader();\n      reader.onload = ()=>{\n        const img = new Image();\n        img.onload = ()=>{\n          // draw centered and scaled\n          ctx.clearRect(0,0,canvas.width,canvas.height);\n          ctx.fillStyle = 'white'; ctx.fillRect(0,0,canvas.width,canvas.height);\n          const s = Math.min(canvas.width/img.width, canvas.height/img.height);\n          const w = img.width * s, h = img.height * s;\n          ctx.drawImage(img, (canvas.width-w)/2, (canvas.height-h)/2, w, h);\n        };\n        img.src = reader.result;\n      };\n      reader.readAsDataURL(f);\n    });\n\n    document.getElementById('clear').addEventListener('click', ()=>{\n      ctx.clearRect(0,0,canvas.width,canvas.height);\n      ctx.fillStyle = 'white'; ctx.fillRect(0,0,canvas.width,canvas.height);\n      document.getElementById('result').textContent = 'Result: -';\n    });\n\n    document.getElementById('predict').addEventListener('click', async ()=>{\n      const dataUrl = canvas.toDataURL('image/png');\n      const res = await fetch(`/predict/{{ model }}`, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ image: dataUrl })\n      });\n      const json = await res.json();\n      if(json.error){\n        document.getElementById('result').textContent = 'Error: ' + json.error;\n      } else {\n        document.getElementById('result').textContent = `Result: ${json.class} (conf ${Math.round(json.confidence*100)}%)`;\n      }\n    });\n    </script>\n  </body>\n</html>\n", "app/templates/index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Model selector</title>\n  </head>\n  <body>\n    <h1>Available models</h1>\n    <ul>\n      {% for m in models %}\n        <li>\n          <a href=\"{{ m.url }}\">{{ m.display }}</a>\n          - {% if m.available %}available{% else %}missing (place model file){% endif %}\n        </li>\n      {% endfor %}\n    </ul>\n    <p>MNIST has a drawing UI at the MNIST page; other models accept image upload/drag-and-drop.</p>\n  </body>\n</html>\n", "app/templates/draw.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Document</title>\n</head>\n<body>\n    <h2>Draw a digit (0-9)</h2>\n    <canvas id=\"canvas\" width=\"280\" height=\"280\" style=\"border:1px solid #333; touch-action: none;\"></canvas>\n    <div>\n        <button id=\"clear\">Clear</button>\n        <button id=\"predict\">Predict</button>\n    </div>\n    <p id=\"result\">Result: -</p>\n\n    <script>\n    const canvas = document.getElementById('canvas');\n    const ctx = canvas.getContext('2d');\n    ctx.fillStyle = 'white';\n    ctx.fillRect(0,0,canvas.width,canvas.height);\n    ctx.lineWidth = 18;\n    ctx.lineCap = 'round';\n    ctx.strokeStyle = 'black';\n\n    let drawing = false;\n\n    function pointerDown(e){ drawing = true; draw(e); }\n    function pointerUp(){ drawing = false; ctx.beginPath(); }\n    function draw(e){\n        if(!drawing) return;\n        const rect = canvas.getBoundingClientRect();\n        const x = (e.clientX || e.touches[0].clientX) - rect.left;\n        const y = (e.clientY || e.touches[0].clientY) - rect.top;\n        ctx.lineTo(x, y);\n        ctx.stroke();\n        ctx.beginPath();\n        ctx.moveTo(x, y);\n    }\n\n    canvas.addEventListener('pointerdown', pointerDown);\n    canvas.addEventListener('pointerup', pointerUp);\n    canvas.addEventListener('pointermove', draw);\n    canvas.addEventListener('touchstart', (e)=>{ e.preventDefault(); pointerDown(e.touches[0]); });\n    canvas.addEventListener('touchend', pointerUp);\n    canvas.addEventListener('touchmove', (e)=>{ e.preventDefault(); draw(e.touches[0]); });\n\n    document.getElementById('clear').addEventListener('click', ()=>{\n        ctx.clearRect(0,0,canvas.width,canvas.height);\n        ctx.fillStyle = 'white'; ctx.fillRect(0,0,canvas.width,canvas.height);\n        document.getElementById('result').textContent = 'Result: -';\n    });\n\n    document.getElementById('predict').addEventListener('click', async ()=>{\n        const dataUrl = canvas.toDataURL('image/png');\n        const res = await fetch('/predict', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ image: dataUrl })\n        });\n        const json = await res.json();\n        if(json.error){\n            document.getElementById('result').textContent = 'Error: ' + json.error;\n        } else {\n            document.getElementById('result').textContent = `Result: ${json.digit} (conf ${Math.round(json.confidence*100)}%)`;\n        }\n    });\n    </script>\n</body>\n</html>", "requirements.txt": "Flask>=3.0,<4\ntensorflow>=2.15,<3\nh5py>=3.10,<4\nnumpy>=1.26,<3\nPillow>=10.0,<11\nmatplotlib>=3.8,<4", "Dockerfile": "FROM python:3.12-slim\n\nENV PYTHONDONTWRITEBYTECODE=1 \\\n    PYTHONUNBUFFERED=1\n\nWORKDIR /TP4\n\n# Dépendances d'abord : ce calque reste en cache tant que requirements.txt ne change pas\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\n\nCOPY . .\n\nEXPOSE 5005\n\nCMD [\"python\", \"exo.py\"]\n", "docker-compose.yml": "services:\n  flask_app:\n    build: .\n    ports:\n      - \"5005:5005\"\n    volumes:\n      - .:/TP4\n    container_name: Group5_flask_app", "tests/run_tests.sh": "#!/usr/bin/env bash\nset -euo pipefail\n\nBASE_URL=\"http://localhost:5005\"\necho \"Testing TP4 Flask app at $BASE_URL\"\n\necho -n \"GET / -> \"\ncurl -sS -o /dev/null -w \"%{http_code}\\n\" \"$BASE_URL/\"\n\nfor path in \"/model/mnist\" \"/model/fashion_mnist\" \"/model/cifar10\" \"/model/cifar100\"; do\n  echo -n \"GET $path -> \"\n  curl -sS -o /dev/null -w \"%{http_code}\\n\" \"$BASE_URL$path\"\ndone\n\necho \"POST /predict/mnist with blank image ->\"\npython3 - <<'PY' | curl -sS -X POST -H \"Content-Type: application/json\" --data @- $BASE_URL/predict/mnist\nfrom PIL import Image\nimport io, base64, json\nimg = Image.new('L', (280,280), color=255)\nbuf = io.BytesIO()\nimg.save(buf, format='PNG')\nb64 = base64.b64encode(buf.getvalue()).decode('ascii')\nprint(json.dumps({'image': 'data:image/png;base64,'+b64}))\nPY\n\necho\necho \"POST /predict/fashion_mnist (expect error if model missing) ->\"\npython3 - <<'PY' | curl -sS -X POST -H \"Content-Type: application/json\" --data @- $BASE_URL/predict/fashion_mnist\nfrom PIL import Image\nimport io, base64, json\nimg = Image.new('RGB', (280,280), color=(255,255,255))\nbuf = io.BytesIO()\nimg.save(buf, format='PNG')\nb64 = base64.b64encode(buf.getvalue()).decode('ascii')\nprint(json.dumps({'image': 'data:image/png;base64,'+b64}))\nPY\n\necho\necho \"All tests executed.\"\n"}});
